/// Raw PNG bytes of the app logo.
final Uint8List kAppLogoBytes = base64Decode(_logoBase64);

/// The ArxivLibrary logo: the gold-book mark (transparent background).
class AppLogoImage extends StatelessWidget {
  const AppLogoImage({super.key, this.size = 28});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      kAppLogoBytes,
      width: size,
      height: size,
      fit: BoxFit.contain,
      gaplessPlayback: true,
    );
  }
}
